package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.model.CategoryResponseimport com.dy.artisan3d.domain.model.Categoryimport com.dy.artisan3d.domain.repository.CategoryRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.Constants.FILE_URLimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getclass CategoryRepositoryImpl(    private val httpClient: HttpClient) : CategoryRepository {    override suspend fun getCategories(lang: String): List<Category> {        val response: CategoryResponse = httpClient.get(BASE_URL+"categories").body()        return response.data.map { dto ->            Category(                id = dto.id,                // Berilgan til bo'yicha nomni olamiz, topilmasa "uz" ni ishlatamiz                name = dto.translations[lang]?.name ?: dto.translations["uz"]?.name ?: "",                iconUrl = FILE_URL + dto.icon            )        }    }}